}

(function boot() {
  rtcState = rtcProbe();
  var r = rtcRead();
  if (r >= 0) anchor(r);
  else anchor(loadNum('clock_utc', 10 * 3600));
})();

function utcNow() { return (anchorUtc + (sys.millis() - anchorMs) / 1000) % DAY; }
