function Words(t) {
  return h('box', { gap: em(0.4), pad: em(0.5) }, [
    h('text', { text: words(t), size: 2, align: 'center', wrap: true }),
    h('text', { text: two(t.h) + ':' + two(t.m) + ':' + two(t.s),
